interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

type EventType = "order" | "cancel" | "ship" | "restock" | "expire";

interface RawEvent {
  type?: unknown;
  id?: unknown;
  item?: unknown;
  qty?: unknown;
}

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function isNonEmptyString(value: unknown): value is string {
  return typeof value === "string" && value.length > 0;
}

function isPositiveInt(value: unknown): value is number {
  return Number.isInteger(value) && (value as number) >= 1;
}

function stockOf(stock: Record<string, number>, item: string): number {
  return stock[item] === undefined ? 0 : stock[item];
}

/**
 * Walk the backorder queue in FIFO order, fulfilling as many pending orders as
 * current stock allows. Mutates all shared state in place.
 */
function fulfillQueue(
  stock: Record<string, number>,
  reserved: Record<string, Want>,
  pendingWants: Record<string, Want>,
  queue: string[],
  orders: Record<string, string>,
): void {
  for (let position = 0; position < queue.length; position++) {
    const pendingId = queue[position];
    const want = pendingWants[pendingId];
    if (stockOf(stock, want.item) >= want.qty) {
      stock[want.item] = stockOf(stock, want.item) - want.qty;
      reserved[pendingId] = { item: want.item, qty: want.qty };
      orders[pendingId] = "reserved";
      delete pendingWants[pendingId];
      queue.splice(position, 1);
      position = position - 1;
    }
  }
}

export function processEvents(raw: unknown): FulfillmentResult {
  if (!isObject(raw)) {
    return { ok: false, error: "malformed input" };
  }

  const input = raw as Record<string, unknown>;
  if (!isObject(input.stock)) {
    return { ok: false, error: "bad stock" };
  }

  const stock: Record<string, number> = {};
  for (const item of Object.keys(input.stock as Record<string, unknown>)) {
    if (!Number.isInteger(input.stock[item]) || (input.stock[item] as number) < 0) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = input.stock[item] as number;
  }

  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const orders: Record<string, string> = {};
  const reserved: Record<string, Want> = {};
  const pendingWants: Record<string, Want> = {};
  const queue: string[] = [];
  let rejected = 0;

  const events = input.events as unknown[];

  for (let index = 0; index < events.length; index++) {
    const event = events[index];
    if (!isObject(event)) {
      return { ok: false, error: "event " + index + ": malformed" };
    }

    const ev = event as unknown as RawEvent;

    switch (ev.type) {
      case "order": {
        if (!isNonEmptyString(ev.id)) return { ok: false, error: "event " + index + ": bad id" };
